                if grid[i][j] == 9 or out[i][j] == 3:
                    continue
                # Chebyshev distance to any cell of this component
                # we only need to check distance 2 to the component's bounding box
                if i >= rmin-2 and i <= rmax+2 and j >= cmin-2 and j <= cmax+2:
                    # distance <=2?
