                       max(abs(i-rmin), abs(j-cmax)) <= 2 or \
                       max(abs(i-rmax), abs(j-cmin)) <= 2 or \
                       max(abs(i-rmax), abs(j-cmax)) <= 2:
                        # also require at least one neighbor is already 3
                        has_neighbor = False
                        for dr,dc in dirs:
                            ni,nj = i+dr,j+dc
                            if 0 <= ni < n and 0 <= nj < m and out[ni][nj] == 3:
                                has_neighbor = True
                                break
                        if has_neighbor:
                            out[i][j] = 3
